import { FaRegCopy, FaExternalLinkAlt, FaHeart, FaLink } from 'react-icons/fa';
import React from 'react';
import { Link } from '../ui/link';
import { Text } from '../ui/text';
import { formatTweetText } from './TweetEntities';
import { Box, Divider, HStack, Stack, styled } from 'styled-system/jsx';
import type { PrunedTweet } from '~/utils/prune-tweets';
import { formatProfilePictureUrl } from '~/utils/image';
import { getCharacterByXAccount } from '~/utils/character-data';
import { getAssetUrl } from '~/utils/assets';
import { css } from 'styled-system/css';

interface TweetProps {
  tweet: PrunedTweet;
  hideBottom?: boolean;
  hideInfo?: boolean;
  showLine?: boolean;
  quoted?: boolean;
  useEnglishName?: boolean;
  onCopy?: (text: string, type: 'text' | 'link') => void;
  children?: React.ReactNode;
}

export function Tweet({
  tweet,
  hideBottom,
  hideInfo,
  showLine,
  quoted,
  useEnglishName,
  onCopy,
  children
}: TweetProps) {
  const tweetDate = new Date(tweet.createdAt);
  const today = new Date();
  const isToday =
    tweetDate.getDate() === today.getDate() &&
    tweetDate.getMonth() === today.getMonth() &&
    tweetDate.getFullYear() === today.getFullYear();

  const dateTimeOptions: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'numeric',
    day: 'numeric'
  };

  if (isToday) {
    dateTimeOptions.hour = '2-digit';
    dateTimeOptions.minute = '2-digit';
  }

  const character = getCharacterByXAccount(tweet.author.userName);

  const PRE_RELEASE_DATE = new Date('2025-05-12T00:00:00Z');
  const isBeforePublic = tweetDate < PRE_RELEASE_DATE;
  const isBeforeJoin =
    character?.joinDate && tweetDate > PRE_RELEASE_DATE && tweetDate < new Date(character.joinDate);

  const profilePicture = isBeforePublic
    ? getAssetUrl(character?.prePublicData.image ?? '')
    : formatProfilePictureUrl(tweet.author.profilePicture);

  const baseName = isBeforePublic
    ? character?.prePublicData.name
    : useEnglishName && character
      ? `${character.englishName}@IKIZULIVE!`
      : tweet.author.name;

  const displayName = isBeforeJoin ? baseName?.split('@')[0] : baseName;

  return (
    <Box
      className="tweet"
      data-tweet-id={tweet.id}
      cursor="pointer"
      display="flex"
      borderBottomWidth={hideBottom ? '0' : '1px'}
      borderColor="border.default"
      px={quoted ? 0 : '4'}
      pt={hideInfo || quoted ? 0 : '4'}
      pb={hideBottom || quoted ? 0 : '4'}
      transitionDuration="200ms"
      transitionProperty="colors"
      _hover={{ bg: 'bg.subtle' }}
    >
      <Box
        display="flex"
        gap="3"
        alignItems="flex-start"
        w="full"
        textDecoration="unset"
        _hover={{ textDecoration: 'unset' }}
      >
        <Stack gap="0" flexShrink="0" alignItems="center" w={quoted ? '8' : '12'} h="full">
          {!hideInfo && (
            <Box
              borderRadius="full"
              w={quoted ? '8' : '12'}
              h={quoted ? '8' : '12'}
              overflow="hidden"
            >
              <styled.img
                src={profilePicture}
                alt={tweet.author.name}
                transform="scale(1.1)"
                objectFit="cover"
                w={quoted ? '8' : '12'}
                h={quoted ? '8' : '12'}
              />
            </Box>
          )}
          {showLine && (
            <Box
              flex="1"
              borderLeft="3px solid"
              borderLeftColor="border.muted"
              height="full"
              mb={!hideBottom ? '8' : 0}
            ></Box>
          )}
        </Stack>
        <Stack gap="0" direction="column" flexGrow="1" minW="0" h="full" overflow="hidden">
          {!hideInfo && (
            <HStack gap="1" alignItems="center" mb="0.5" flexWrap="wrap">
              <HStack flexGrow="1" alignItems="center">
                <Text
                  color="fg.default"
                  textOverflow="ellipsis"
                  textWrap="nowrap"
                  fontSize={quoted ? 'sm' : 'base'}
                  fontWeight="bold"
                  overflow="hidden"
                >
                  {displayName}
                </Text>
                <Text
                  color="fg.muted"
                  textOverflow="ellipsis"
                  textWrap="nowrap"
                  fontSize={quoted ? 'xs' : 'sm'}
                  overflow="hidden"
                >
                  @{tweet.author.userName}
                </Text>
              </HStack>
              <Text color="fg.muted" fontSize={quoted ? 'xs' : 'sm'}>
                {tweetDate.toLocaleString([], dateTimeOptions)}
              </Text>
            </HStack>
          )}
          <Text
            flex="1"
            w="full"
            h="full"
            mt={hideInfo ? '4' : 0}
            color="fg.default"
            wordBreak="break-word"
            fontSize={quoted ? 'sm' : 'base'}
            whiteSpace="pre-wrap"
          >
            {formatTweetText(tweet.text, tweet.entities)}
          </Text>
          {(tweet.quoted_tweet || tweet.retweeted_tweet) && (
            <Box border="1px solid" borderColor="border.default" rounded="xl" mt="2" p={2}>
              {tweet.retweeted_tweet && (
                <Tweet
                  tweet={tweet.retweeted_tweet}
                  onCopy={onCopy}
                  hideBottom
                  quoted
                  useEnglishName={useEnglishName}
                />
              )}
              {tweet.quoted_tweet && (
                <Tweet
                  tweet={tweet.quoted_tweet}
                  onCopy={onCopy}
                  hideBottom
                  quoted
                  useEnglishName={useEnglishName}
                />
              )}
            </Box>
          )}
          {children && children}

          {hideBottom && !quoted && <Divider mt="4" borderStyle="dashed" />}
          {!hideBottom && (
            <HStack justifyContent="space-between" h="full" mt="2" color="fg.subtle">
              <HStack
                onClick={(e) => {
                  e.preventDefault();
                  onCopy?.(tweet.text, 'text');
                }}
                cursor="pointer"
                justifyContent="center"
                alignItems="center"
                spaceX="1"
                color="fg.subtle"
              >
                <FaRegCopy className={css({ w: 4, h: 4 })} />
              </HStack>
              <Link
                href={tweet.twitterUrl}
                target="_blank"
                rel="noopener noreferrer"
                color="fg.subtle"
              >
                <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                  <FaExternalLinkAlt className={css({ w: 4, h: 4 })} />
                </HStack>
              </Link>
              <HStack cursor="pointer" justifyContent="center" alignItems="center" spaceX="1">
                <FaHeart className={css({ w: 4, h: 4 })} />
              </HStack>
              <HStack
                onClick={(e) => {
                  e.preventDefault();
                  onCopy?.(tweet.url, 'link');
                }}
                cursor="pointer"
                justifyContent="center"
                alignItems="center"
                spaceX="1"
              >
                <FaLink className={css({ w: 4, h: 4 })} />
              </HStack>
              <Box />
            </HStack>
          )}
        </Stack>
      </Box>
    </Box>
  );
}
