import { useEffect, useRef } from 'react';
import { Button } from '../ui/button';
import { Box } from 'styled-system/jsx';

import type { MonthYearCount } from '~/hooks/useBluebirdMonthsYears';

interface LoadingIndicatorProps {
  isLoading: boolean;
  hasMore: boolean;
  onIntersect?: () => void;
  selectedMonthYear?: string;
  monthsYears?: MonthYearCount[];
  onMonthYearClick?: (monthYear: string) => void;
}

export function LoadingIndicator({
  isLoading,
  hasMore,
  onIntersect,
  selectedMonthYear,
  monthsYears,
  onMonthYearClick
}: LoadingIndicatorProps) {
  const loadingRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!loadingRef.current) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && hasMore && !isLoading) {
          onIntersect?.();
        }
      },
      {
        rootMargin: '0px',
        threshold: 0.1
      }
    );

    observer.observe(loadingRef.current);

    return () => {
      observer.disconnect();
    };
  }, [isLoading, hasMore, onIntersect]);

  return (
    <Box
      ref={loadingRef}
      mb={{ mdDown: '20' }}
      p="5"
      color="fg.muted"
      textAlign="center"
      fontSize="sm"
      fontStyle="italic"
    >
      {isLoading
        ? 'Loading more tweets...'
        : hasMore
          ? 'Scroll down to load more'
          : monthsYears && selectedMonthYear && monthsYears.length > 0
            ? (() => {
                const currentIndex = monthsYears.findIndex(
                  (item) => item.monthYear === selectedMonthYear
                );
                const nextMonthYear = monthsYears[currentIndex + 1]?.monthYear;
                if (nextMonthYear) {
                  return (
                    <Button
                      variant="link"
                      onClick={() => onMonthYearClick?.(nextMonthYear)}
                      cursor="pointer"
                    >
                      No more tweets for this month. Try{' '}
                      {new Date(nextMonthYear).toLocaleString('en-US', {
                        month: 'long',
                        year: 'numeric'
                      })}
                      ?
                    </Button>
                  );
                } else {
                  return 'No more tweets.';
                }
              })()
            : 'No more tweets.'}
    </Box>
  );
}
